// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, string memory description) public {
        vm.assume(caller != address(0));
        vm.assume(bytes(description).length <= 32);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("newEmergencyOracle(string)", description));
        assertTrue(success == c.isAdmin(caller));
    }
}

